import{_ as n,C as e,o as p,c as d,a2 as s,E as r}from"./chunks/framework.B4hAkGey.js";const u=JSON.parse('{"title":"1.3 实战案例：5G 场景下 WebRTC 的优势定位","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01-overview/practice.md","filePath":"guide/01-overview/practice.md","lastUpdated":1792683941000}'),l={name:"guide/01-overview/practice.md"};function o(i,t,c,h,b,g){const a=e("LiveRunner");return p(),d("div",null,[t[0]||(t[0]=s(`<h1 id="_1-3-实战案例-5g-场景下-webrtc-的优势定位" tabindex="-1">1.3 实战案例：5G 场景下 WebRTC 的优势定位 <a class="header-anchor" href="#_1-3-实战案例-5g-场景下-webrtc-的优势定位" aria-label="Permalink to &quot;1.3 实战案例：5G 场景下 WebRTC 的优势定位&quot;">​</a></h1><blockquote><p>把 WebRTC + 5G 组合的优势落到具体业务场景，建立&quot;什么时候用 WebRTC、什么时候用 RTMP&quot;的决策直觉。</p></blockquote><hr><h2 id="_1-3-1-场景决策矩阵" tabindex="-1">1.3.1 场景决策矩阵 <a class="header-anchor" href="#_1-3-1-场景决策矩阵" aria-label="Permalink to &quot;1.3.1 场景决策矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>实时性要求</th><th>并发量</th><th>推荐方案</th><th>原因</th></tr></thead><tbody><tr><td>电商直播（带货）</td><td>低（5~30 秒可接受）</td><td>高（10w+）</td><td><strong>WebRTC + SFU</strong> 或 RTMP</td><td>需要时切换互动</td></tr><tr><td>直播连麦 PK</td><td><strong>高（&lt; 300ms）</strong></td><td>中（1w+）</td><td><strong>WebRTC + SFU</strong></td><td>RTMP 做不到低延迟互动</td></tr><tr><td>在线教育互动</td><td><strong>高（&lt; 200ms）</strong></td><td>中（5k+）</td><td><strong>WebRTC + SFU + MCU</strong></td><td>需要多路合流录制</td></tr><tr><td>云游戏 / 云桌面</td><td><strong>极高（&lt; 100ms）</strong></td><td>低~中</td><td><strong>WebRTC + 专用编码器</strong></td><td>端到端必须低延迟</td></tr><tr><td>竞技直播（电竞赛事）</td><td>高（&lt; 300ms）</td><td>高</td><td><strong>WebRTC + SFU + 5G MEC</strong></td><td>低延迟 + 边缘分发</td></tr><tr><td>企业视频会议</td><td>高</td><td>低~中</td><td>WebRTC MCU</td><td>多路混音</td></tr><tr><td>安防监控</td><td>中</td><td>高</td><td>WebRTC 拉流</td><td>浏览器原生支持，无需插件</td></tr><tr><td>远程医疗</td><td><strong>极高（&lt; 50ms）</strong></td><td>低</td><td><strong>WebRTC + 5G URLLC</strong></td><td>医疗级时延要求</td></tr></tbody></table><p><strong>核心判断标准</strong>：是否需要<strong>互动</strong>（双工或多向）。需要互动 → WebRTC；纯播放 → RTMP/HLS/DASH。</p><hr><h2 id="_1-3-2-5g-webrtc-直播延迟预算" tabindex="-1">1.3.2 5G + WebRTC 直播延迟预算 <a class="header-anchor" href="#_1-3-2-5g-webrtc-直播延迟预算" aria-label="Permalink to &quot;1.3.2 5G + WebRTC 直播延迟预算&quot;">​</a></h2><p>完整分解一帧画面在 5G 网络下的端到端延迟：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>采集 ──► 编码 ──► 传输 ──► 转发 ──► 传输 ──► 解码 ──► 渲染</span></span>
<span class="line"><span>│       │        │       │       │       │       │</span></span>
<span class="line"><span>│~1ms   │5~15ms  │3~10ms │5~20ms │3~10ms  │5~15ms │~5ms</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                    总计 ≈ 30~70ms（5G 下）</span></span></code></pre></div><p>对比 4G + RTMP：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>采集 ──► 编码 ──► RTMP ──► CDN ──► HLS ──► 解码 ──► 渲染</span></span>
<span class="line"><span>│       │        │        │       │       │       │</span></span>
<span class="line"><span>│~1ms   │10~30ms │300ms   │100ms  │1000ms  │10~30ms│200ms</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                    总计 ≈ 1.6~2.0 秒</span></span></code></pre></div><p><strong>关键差距</strong>：WebRTC 不做 GOP 缓存，直接逐帧传输。5G 把传输延迟进一步压低到两位数毫秒。</p><hr><h2 id="_1-3-3-动手-环境检测脚本" tabindex="-1">1.3.3 动手：环境检测脚本 <a class="header-anchor" href="#_1-3-3-动手-环境检测脚本" aria-label="Permalink to &quot;1.3.3 动手：环境检测脚本&quot;">​</a></h2><p>点击下方「▶ 运行」直接在线跑，也可编辑后再运行（或把代码存为 <code>check-env.html</code>，用 <code>npx serve .</code> 本地启动访问）：</p>`,16)),r(a,{src:"01-env-check.html",title:"WebRTC × 5G 环境自检"}),t[1]||(t[1]=s(`<p>运行后你会看到：</p><ul><li>当前安全上下文状态</li><li>浏览器暴露的 WebRTC API</li><li>Network Information API 给出的连接类型（<code>4g</code> 基本代表 5G 或 LTE-A Pro）</li><li>启发式判断是否处于 5G 网络</li></ul><hr><h2 id="_1-3-4-下一阶段路线图" tabindex="-1">1.3.4 下一阶段路线图 <a class="header-anchor" href="#_1-3-4-下一阶段路线图" aria-label="Permalink to &quot;1.3.4 下一阶段路线图&quot;">​</a></h2><p>基于 WebRTC + 5G 能力，你的产品可以按以下路线演进：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段 1 · 基础能力（第 2~5 章）</span></span>
<span class="line"><span>  ├─ 摄像头采集 + PeerConnection 一对一通话</span></span>
<span class="line"><span>  └─ WebSocket 信令 + Coturn TURN</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段 2 · 多人直播（第 7~8 章）</span></span>
<span class="line"><span>  ├─ Mediasoup / Janus SFU 部署</span></span>
<span class="line"><span>  ├─ 多房间 + 多人连麦</span></span>
<span class="line"><span>  └─ WebRTC → RTMP 转推（兼容传统 CDN）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段 3 · 5G 优化（第 6、9 章）</span></span>
<span class="line"><span>  ├─ 5G MEC 边缘 SFU 部署</span></span>
<span class="line"><span>  ├─ 基于 QFI 的 QoS 调度</span></span>
<span class="line"><span>  ├─ 移动端智能码率切换</span></span>
<span class="line"><span>  └─ NWDAF 网络数据分析</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段 4 · 生产落地（第 10 章）</span></span>
<span class="line"><span>  ├─ 全链路监控（质量数据 + 网络数据）</span></span>
<span class="line"><span>  ├─ 弱网降级策略（自动切 RTMP）</span></span>
<span class="line"><span>  └─ 合规（加密、隐私、数据主权）</span></span></code></pre></div><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你应该记住</th><th></th></tr></thead><tbody><tr><td><strong>WebRTC 是什么</strong></td><td>浏览器内置的实时通信栈，三件套：getUserMedia + PeerConnection + DataChannel</td></tr><tr><td><strong>5G 怎么帮 WebRTC</strong></td><td>eMBB（大上行带宽）、URLLC（空口 &lt; 10ms）、MEC（边缘部署）、切片（QoS 保障）</td></tr><tr><td><strong>何时用 WebRTC</strong></td><td>需要<strong>互动</strong>（多向实时）的场景。纯播放用 RTMP/HLS。</td></tr><tr><td><strong>5G 也有坑</strong></td><td>IPv6-only、网络抖动、电量消耗——需要针对性处理</td></tr></tbody></table><hr><h2 id="进入下一章-→" tabindex="-1">进入下一章 → <a class="header-anchor" href="#进入下一章-→" aria-label="Permalink to &quot;进入下一章 →&quot;">​</a></h2><p>→ <a href="./../02-media-capture/basics">模块二 · 媒体采集与处理</a></p>`,12))])}const C=n(l,[["render",o]]);export{u as __pageData,C as default};
